<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\Accessor\UserPersonalApiKeyKeyHashAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPersonalApiKeyKeyHashAccessor trait.
 *
 * Covers null default, string/VO assignment via withKeyHash,
 * getKeyHash/keyHash accessors, and isKeyHashChanged with/without original.
 */
class UserPersonalApiKeyKeyHashAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withKeyHash creates a new instance with the KeyHash set
     * from a string value, and getKeyHash returns the primitive string.
     */
    public function testWithKeyHashFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyKeyHashAccessorUnitTest();

        // Act
        $result = $holder->withKeyHash('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getKeyHash());
    }
    /**
     * Asserts that withkeyHash has access to the value object
     * from a string value, and getKeyHash returns the primitive string.
     */
    public function testWithKeyHashFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyKeyHashAccessorUnitTest();

        // Act
        $result = $holder->withKeyHash('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->keyHash()->value());
    }
    public function testChangedKeyHash(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyKeyHashAccessorUnitTest()->withKeyHash('one');
        $original = $holder->withKeyHash('one');
        $same = $holder->withKeyHash('one');
        $modified = $holder->withKeyHash('other');

        // Act
        $withSame = $original->isKeyHashChanged($same);
        $withDiferent = $original->isKeyHashChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserPersonalApiKeyKeyHashAccessorUnitTest
{
    use UserPersonalApiKeyKeyHashAccessor;
}
